window.abrirFoto=function(n){const o=window.open("","_blank");if(!o)return void alert("Popup bloqueado pelo navegador.");n=(n||"").trim();try{n=decodeURIComponent(n)}catch(n){}const e=o.document;e.open(),e.write("\n    <html>\n      <head>\n        <title>Visualizar imagem</title>\n        <style>\n          body {\n            margin: 0;\n            background: #111;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            min-height: 100vh;\n          }\n          img {\n            max-width: 100%;\n            max-height: 100vh;\n            object-fit: contain;\n          }\n        </style>\n      </head>\n      <body></body>\n    </html>\n  "),e.close();const i=e.createElement("img");i.onload=function(){console.log("Imagem carregada:",n)},i.onerror=function(){e.body.innerHTML=`\n      <div style="color:#fff;font-family:Arial;padding:30px;text-align:center;">\n        Erro ao carregar imagem<br><br>\n        ${n}\n      </div>\n    `},i.src=n,e.body.appendChild(i)},window.abrirArquivo=function(n){window.open("https://docs.google.com/gview?embedded=true&url="+encodeURIComponent(n),"_blank")},window.abrirArquivoxml=function(n){window.open(n,"_blank")};